package Builder.ash;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

public final class NlibEmbedded {

    private NlibEmbedded() { }

    private static final Map<String, String[]> DATA = new LinkedHashMap<>();

    static {
        DATA.put("args.ash", f0());
        DATA.put("delay.ash", f1());
        DATA.put("math.ash", f2());
        DATA.put("null.ash", f3());
        DATA.put("stdbool.ash", f4());
        DATA.put("stdio.ash", f5());
        DATA.put("stdlib.ash", f6());
        DATA.put("string.ash", f7());
        DATA.put("syscalls.ash", f8());
        DATA.put("types.ash", f9());
    }

    private static String[] f0() {
        return new String[] {
            "",
        };
    }

    private static String[] f1() {
        return new String[] {
            "",
        };
    }

    private static String[] f2() {
        return new String[] {
            "",
        };
    }

    private static String[] f3() {
        return new String[] {
            "",
        };
    }

    private static String[] f4() {
        return new String[] {
            "",
        };
    }

    private static String[] f5() {
        return new String[] {
            "",
        };
    }

    private static String[] f6() {
        return new String[] {
            "",
            "",
            "",
        };
    }

    private static String[] f7() {
        return new String[] {
            "",
            "",
        };
    }

    private static String[] f8() {
        return new String[] {
            "",
        };
    }

    private static String[] f9() {
        return new String[] {
            "",
        };
    }

    public static List<String> names() {
        return new ArrayList<>(DATA.keySet());
    }

    public static boolean has(String name) {
        return DATA.containsKey(name);
    }

    public static byte[] bytes(String name) {
        String[] parts = DATA.get(name);
        if (parts == null) return null;
        StringBuilder b = new StringBuilder();
        for (String p : parts) b.append(p);
        return Base64.getDecoder().decode(b.toString());
    }

    public static String text(String name) {
        byte[] b = bytes(name);
        return b == null ? null : new String(b, java.nio.charset.StandardCharsets.UTF_8);
    }

    private static Path dir;

    public static synchronized Path currentDir() {
        return dir;
    }

    public static synchronized Path materialize() {

        if (dir != null && Files.isDirectory(dir))
            return dir;

        try {
            final Path d = Files.createTempDirectory("ashc-nlib-");

            for (String n : DATA.keySet()) {
                Path f = d.resolve(n);
                if (f.getParent() != null) Files.createDirectories(f.getParent());
                Files.write(f, bytes(n));
            }

            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                try (java.util.stream.Stream<Path> s = Files.walk(d)) {
                    s.sorted(Comparator.reverseOrder()).forEach(p -> {
                        try { Files.deleteIfExists(p); } catch (IOException ignored) { }
                    });
                } catch (IOException ignored) { }
            }));

            dir = d;
            return d;

        } catch (IOException e) {
            throw new IllegalStateException("no se pudo extraer nlib embebida: " + e.getMessage());
        }
    }
}

